<template><el-sub-menu v-if="menu.children?.length" :index="String(menu.id)"><template #title><el-icon v-if="icon"><component :is="icon" /></el-icon><span>{{ menu.menuName }}</span></template><MenuNode v-for="child in menu.children" :key="child.id" :menu="child" /></el-sub-menu><el-menu-item v-else :index="menu.routePath"><el-icon v-if="icon"><component :is="icon" /></el-icon><template #title>{{ menu.menuName }}</template></el-menu-item></template>
<script setup>import { computed } from 'vue'; const props=defineProps({menu:Object}); const icon=computed(()=>props.menu.icon || 'Menu');</script>
